using System;
using System.IO;
using ICSharpCode.Decompiler;
using ICSharpCode.Decompiler.CSharp;
using ICSharpCode.Decompiler.Metadata;

namespace ILSpyScript
{
    class Program
    {
        static void Main(string[] args)
        {
            if (args.Length < 2)
            {
                Console.WriteLine("Usage: decompile <input-dll-path> <output-path>");
                return;
            }

            string inputFilePath = args[0];
            string outputFilePath = args[1];

            try
            {
                var file = new PEFile(inputFilePath);
                var decompiler = new CSharpDecompiler(file, new DecompilerSettings());
                var code = decompiler.DecompileWholeModuleAsString();

                File.WriteAllText(outputFilePath, code);
                Console.WriteLine($"Decompiled code saved to {outputFilePath}");
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error during decompilation: {e.Message}");
            }
        }
    }
}

