from dnfile import dnPE

def extract_strings(file_path):
    extracted = []
    dnpe = dnPE(file_path)

    for table in dnpe.net.meta_data.tables.values():
        for row in table.rows:
            try:
                if isinstance(row, dnpe.net.directory.metadata.tables.rows.StringsHeapRecord):
                    decoded_string = row.data.decode()
                    extracted.append(decoded_string)
            except UnicodeDecodeError:
                continue

    return extracted

